_BASE_TEST = _FW_HEADER + """package taf.runtime;

import com.microsoft.playwright.Browser;
import com.microsoft.playwright.BrowserContext;
import com.microsoft.playwright.BrowserType;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.Playwright;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Optional;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.api.extension.TestWatcher;

/**
 * One fresh context+page per test; one browser per run. All SUT facts
 * come from the SutProfile SPI — the framework never names a SUT.
 * @concept CONCEPT-playwright-v1-001-01-browser-context-page-hierarchy
 * @concept CONCEPT-taf-v1-004-01-the-artifacts
 * @concept CONCEPT-testing-v1-004-01-the-rerun
 */
@ExtendWith(RerunCondition.class)
public abstract class BaseTest implements TestWatcher {
    protected static String baseUrl = "";
    protected static Path runDir = Path.of(
        System.getenv().getOrDefault("TAF_RESULTS", "results"),
        LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss")));
    protected static Playwright playwright;
    protected static Browser browser;
    protected BrowserContext context;
    protected Page page;
    protected SoftChecks soft;
    protected String testId = "";

    @BeforeAll
    static void beforeAll() throws IOException {
        SutProfile profile = SutProfile.load();
        baseUrl = System.getenv().getOrDefault("TAF_BASE_URL", profile.baseUrl());
        Files.createDirectories(runDir);
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
            .setHeadless("1".equals(System.getenv("TAF_HEADLESS")))
            .setSlowMo(Double.parseDouble(
                System.getenv().getOrDefault("TAF_SLOWMO", "0"))));
        if (profile.requiresAuth()) {
            // One sign-in in a bootstrap context; the session kept as
            // storage state; every test's fresh context inherits it.
            // @concept CONCEPT-dsl-v1-016-01-the-auth-clause
            // @concept CONCEPT-playwright-v1-008-01-storage-state-reuse
            BrowserContext bctx = browser.newContext();
            Page pg = bctx.newPage();
            try {
                profile.signIn(pg, baseUrl);
            } catch (RuntimeException e) {
                Path setup = runDir.resolve("setup");
                Files.createDirectories(setup);
                Files.writeString(setup.resolve("@@dom@@"), pg.content());
                pg.screenshot(new Page.ScreenshotOptions()
                    .setPath(setup.resolve("@@screenshot@@")));
                bctx.close();
                throw e;
            }
            Path authPath = runDir.resolve("@@auth-state@@");
            bctx.storageState(new BrowserContext.StorageStateOptions().setPath(authPath));
            bctx.close();
            System.setProperty("taf.auth.state", authPath.toString());
        }
        System.out.printf(
            "taf env: base_url=%s headless=%s slowmo=%s video=%s arrive_ms=%s results=%s%n",
            baseUrl,
            "1".equals(System.getenv("TAF_HEADLESS")),
            System.getenv().getOrDefault("TAF_SLOWMO", "0"),
            System.getenv().containsKey("TAF_VIDEO") ? "on" : "off",
            System.getenv().getOrDefault("TAF_ARRIVE_MS", "15000"),
            runDir);
    }

    @BeforeEach
    void setUp(TestInfo info) throws IOException {
        testId = info.getDisplayName();
        TafJournal.begin(runDir, testId);
        BrowserContext.NewContextOptions opts = new BrowserContext.NewContextOptions();
        String auth = System.getProperty("taf.auth.state");
        if (auth != null && !auth.isBlank()) {
            opts.setStorageStatePath(Path.of(auth));
        }
        if (System.getenv().containsKey("TAF_VIDEO")) {
            opts.setRecordVideoDir(TafJournal.testDir());
        }
        context = browser.newContext(opts);
        page = context.newPage();
        soft = new SoftChecks();
    }

    @Override
    public void testFailed(ExtensionContext context, Throwable cause) {
        TafJournal.mark("failed");
        Path d = TafJournal.testDir();
        try {
            page.screenshot(new Page.ScreenshotOptions()
                .setPath(d.resolve("@@screenshot@@")));
            Files.writeString(d.resolve("@@dom@@"), page.content());
        } catch (Exception ignored) {}
        TafJournal.event("fail", java.util.Map.of("test", testId));
        String ws = System.getenv("TAF_IKC3_WS");
        if (ws != null && !ws.isBlank()) {
            try {
                String err = String.valueOf(
                    Optional.ofNullable(cause.getMessage()).orElse("test failed"))
                    .lines().findFirst().orElse("test failed");
                Ikc3Sink.report(ws, "taf journey failed: " + testId + " — " + err,
                    page.url(), page.content(), testId, err);
            } catch (Exception e) {
                System.out.println("ikc3 sink could not file the report: " + e);
            }
        }
        if ("1".equals(System.getenv("TAF_DEBUG"))) {
            page.pause();  // TAF_DEBUG: stop at the failure, browser stays open
        }
    }

    @AfterEach
    void tearDown() throws IOException {
        soft.flush();
        TafJournal.end(TafJournal.failed() ? "failed" : "passed");
        context.close();
    }

    @AfterAll
    static void afterAll() throws IOException {
        if (browser != null) browser.close();
        if (playwright != null) playwright.close();
        Files.writeString(runDir.resolve("@@failed@@"), Ikc3Sink.lastFailed());
        System.out.println("\\nresults → " + runDir);
    }
}
"""


